head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/**
 * @method
 * @name number_format
 * @description desc
 * @param {string} chknum desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.number_format = function(chknum) {
    num = chknum.getValue();
    num = num.split(',').join('');
    var arr = num.split('.');
    var num = new Array();
    for (i = 0; i <= arr[0].length - 1; i++) {
        num[i] = arr[0].substr(arr[0].length - 1 - i, 1);
        if (i % 3 == 0 && i != 0) num[i] += ',';
    }
    num = num.reverse().join('');
    if (!arr[1]) chknum.setValue(num);

    else chknum.setValue(num + '.' + arr[1]);
    scwin.num2won(chknum);
};
/**
 * @method
 * @name num2won
 * @description desc
 * @param {string} chknum desc
 * @param {string} spanid desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.num2won = function(chknum, spanid) {
    val = chknum.getValue();
    var won = new Array();
    re = /^[1-9][0-9]*$/;
    num = val.toString().split(',').join('');
    if (!re.test(num)) {
        chknum.setValue('');
        eval(spanid).innerHTML = '';
        //hanview.innerHTML = '';

    } else {
        var price_unit0 = new Array('', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구');
        var price_unit1 = new Array('', '십', '백', '천');
        var price_unit2 = new Array('', '만', '억', '조', '경', '해', '시', '양', '구', '간', '정');
        for (i = num.length - 1; i >= 0; i--) {
            won[i] = price_unit0[num.substr(num.length - 1 - i, 1)];
            if (i > 0 && won[i] != '') won[i] += price_unit1[i % 4];
            if (i % 4 == 0) won[i] += price_unit2[(i / 4)];
        }
        for (i = num.length - 1; i >= 0; i--) {
            if (won[i].length == 2) won[i - i % 4] += '-';
            if (won[i].length == 1 && i > 0) won[i] = '';
            if (i % 4 != 0) won[i] = won[i].replace('일', '');
        }
        won = won.reverse().join('').replace(/-+/g, '');
        //hanview.innerHTML = '['+won+']';
        eval(spanid).innerHTML = '[' + won + ']';
    }
};
/**
 * @method
 * @name num2won_zero
 * @description desc
 * @param {string} chknum desc
 * @param {string} spanid desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.num2won_zero = function(chknum, spanid) {
    val = chknum.getValue();
    var won = new Array();
    re = /^[0-9]*$/;
    num = val.toString().split(',').join('');

    //alert(num.substring(0,1));
    //첫자리0일 경우 0으로셋팅
    if (num.substring(0, 1) == '0') {
        num = '0';
        chknum.setValue('0');
        eval(spanid).innerHTML = '';
        chknum.select();
    } else {
        if (!re.test(num)) {
            chknum.setValue('');
            eval(spanid).innerHTML = '';
            //hanview.innerHTML = '';

        } else {
            var price_unit0 = new Array('', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구');
            var price_unit1 = new Array('', '십', '백', '천');
            var price_unit2 = new Array('', '만', '억', '조', '경', '해', '시', '양', '구', '간', '정');
            for (i = num.length - 1; i >= 0; i--) {
                won[i] = price_unit0[num.substr(num.length - 1 - i, 1)];
                if (i > 0 && won[i] != '') won[i] += price_unit1[i % 4];
                if (i % 4 == 0) won[i] += price_unit2[(i / 4)];
            }
            for (i = num.length - 1; i >= 0; i--) {
                if (won[i].length == 2) won[i - i % 4] += '-';
                if (won[i].length == 1 && i > 0) won[i] = '';
                if (i % 4 != 0) won[i] = won[i].replace('일', '');
            }
            won = won.reverse().join('').replace(/-+/g, '');
            //hanview.innerHTML = '['+won+']';
            eval(spanid).innerHTML = '[' + won + ']';
        }
    }
};
/**
 * @method
 * @name non_zero
 * @description desc
 * @param {string} chknum desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.non_zero = function(chknum) {
    val = chknum.getValue();
    var won = new Array();
    re = /^[1-9][0-9]*$/;
    num = val.toString().split(',').join('');
    if (!re.test(num)) {
        chknum.setValue('');
    }
};
